    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Residência moderna no centro de Victoria (Gozo), a poucos minutos a pé da estação de ônibus principal; cozinha totalmente equipada, ar-condicionado/aquecimento, máquina de lavar e Wi-Fi de alta velocidade; áreas comuns para convívio com outros estudantes; limpeza semanal com troca de roupa de cama e toalhas; suporte 24/7 da equipe da escola.</p><p>Suplementos e condições: Suplemento de alta temporada: EUR 30/semana (28/jun a 29/ago); Desconto de baixa temporada: EUR 30/semana (3/jan a 28/fev e 1/nov a 31/dez); Suplemento banheiro privativo: EUR 70/semana; Noite extra: EUR 70; Depósito caução (reembolsável): EUR 100; Outro suplemento: EUR 10.5.</p><p>Ajuste sazonal da acomodação, por semana: alta temporada 28/jun a 29/ago +€30; baixa temporada 3/jan a 28/fev e 1/nov a 31/dez -€30; média temporada 1/mar a 27/jun e 30/ago a 31/out sem ajuste. O ajuste não se aplica a reservas de 12+ semanas. Taxa obrigatória: Eco Tax (18+) €10,50 por semana, máximo €22,50 por estadia. Transfer de chegada com check-in €60 (obrigatório) e transfer de saída €60 (opcional); pessoa adicional no mesmo transfer €10. Alteração de reserva €30. Opcionais por semana: banheiro privativo €70 (mediante solicitação, em quarto individual); seguro €17. Noite extra €70 por noite. Depósito caução reembolsável de €100 em dinheiro, recolhido no primeiro dia de aula para quem fica em residência BELS e devolvido no último dia se não houver danos. Semanas calculadas em estadias de 7 noites (check-in sábado/domingo, entrada 15:00 e saída 10:00); noites extras para chegada antecipada ou saída tardia são cobradas à parte. Fonte: BELS Malta Price List 2026 (atualização fev/2026).</p>','["Cozinha Equipada", "Ar-condicionado", "Aquecimento", "Máquina de Lavar", "Wi-Fi", "Áreas Comuns", "Limpeza Semanal", "Troca de Roupa de Cama e Toalhas", "Suporte 24/7", "Ideal para grupos e famílias que preferem independência e cozinhar"]'::jsonb,'["Menos indicado para quem busca imersão com família local"]'::jsonb);
