    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Residência estudantil da LSI Auckland, que equilibra independência e vida social; conta com áreas comuns para conviver com estudantes de várias nacionalidades, limpeza regular e lavanderia.</p><p>Suplementos e condições: Suplemento de alta temporada: EUR 30/semana (28/jun a 29/ago); Desconto de baixa temporada: EUR 30/semana (3/jan a 28/fev e 1/nov a 31/dez); Suplemento banheiro privativo: EUR 70/semana; Suplemento dieta especial: EUR 70/semana; Noite extra: EUR 70; Outro suplemento: EUR 10.5.</p><p>Ajuste sazonal da acomodação, por semana: alta temporada 28/jun a 29/ago +€30; baixa temporada 3/jan a 28/fev e 1/nov a 31/dez -€30; média temporada 1/mar a 27/jun e 30/ago a 31/out sem ajuste. O ajuste não se aplica a reservas de 12+ semanas. Taxa obrigatória: Eco Tax (18+) €10,50 por semana, máximo €22,50 por estadia. Transfer de chegada com check-in €60 (obrigatório) e transfer de saída €60 (opcional); pessoa adicional no mesmo transfer €10. Alteração de reserva €30. Opcionais por semana: banheiro privativo €70 (mediante solicitação, em quarto individual); dieta especial €70 (não cobrada para dietas vegetarianas); seguro €17. Noite extra €70 por noite. Semanas calculadas em estadias de 7 noites (check-in sábado/domingo, entrada 15:00 e saída 10:00); noites extras para chegada antecipada ou saída tardia são cobradas à parte. Fonte: BELS Malta Price List 2026 (atualização fev/2026).</p>','["Áreas Comuns", "Ambiente Internacional", "Limpeza Regular", "Serviço de Lavanderia", "Ideal para amigos que viajam juntos e querem imersão cultural"]'::jsonb,'["Menos indicado para quem busca total independência"]'::jsonb);
