    insert into product_content (product_id, locale, description_html, highlights, exclusions) values (v_pid,'pt-BR','<p>Quarto duplo (twin) compartilhado com outro estudante do mesmo gênero, na categoria Superior Plus com banheiro privativo (ensuite) incluído. Sem plano de refeições — self-catering, com cozinha equipada. Inclui: banheiro privativo, Wi-Fi de alta velocidade, ar-condicionado/aquecimento, máquina de lavar, roupa de cama, toalhas e limpeza semanal. Não inclui: refeições. Valor por pessoa/semana, com desconto progressivo a partir de 8 semanas.</p><p>Suplementos e condições: Suplemento de alta temporada: EUR 30/semana (28/jun a 29/ago); Desconto de baixa temporada: EUR 30/semana (3/jan a 28/fev e 1/nov a 31/dez); Noite extra: EUR 70; Depósito caução (reembolsável): EUR 100; Outro suplemento: EUR 10.5.</p><p>Ajuste sazonal da acomodação, por semana: alta temporada 28/jun a 29/ago +€30; baixa temporada 3/jan a 28/fev e 1/nov a 31/dez -€30; média temporada 1/mar a 27/jun e 30/ago a 31/out sem ajuste. O ajuste não se aplica a reservas de 12+ semanas. Taxa obrigatória: Eco Tax (18+) €10,50 por semana, máximo €22,50 por estadia. Transfer de chegada com check-in €60 (obrigatório) e transfer de saída €60 (opcional); pessoa adicional no mesmo transfer €10. Alteração de reserva €30. Opcionais por semana: seguro €17. Noite extra €70 por noite. Depósito caução reembolsável de €100 em dinheiro, recolhido no primeiro dia de aula para quem fica em residência BELS e devolvido no último dia se não houver danos. Semanas calculadas em estadias de 7 noites (check-in sábado/domingo, entrada 15:00 e saída 10:00); noites extras para chegada antecipada ou saída tardia são cobradas à parte. Fonte: BELS Malta Price List 2026 (atualização fev/2026).</p>','["Residência superior da BELS em Gozo, com quartos de padrão superior e banheiro privativo incluído; cozinha totalmente equipada, ar-condicionado/aquecimento, máquina de lavar e Wi-Fi de alta velocidade; áreas comuns para socializar; limpeza semanal com troca de roupa de cama e toalhas; suporte 24/7 da equipe da escola. Em Gozo, o quarto twin só é possível quando duas pessoas viajam juntas.", "Ideal para quem quer banheiro privativo em Gozo dividindo o quarto com um acompanhante"]'::jsonb,'["Menos indicado para quem viaja sozinho e quer quarto twin, que em Gozo só é liberado para duplas"]'::jsonb);
